package com.trevasq.qguard.service;
import com.trevasq.qguard.config.AppProperties; import com.trevasq.qguard.domain.*; import java.time.*; import java.util.*; import org.springframework.stereotype.Service;
@Service public class SchedulingService { private final BookingRepository repo; private final AppProperties p; public SchedulingService(BookingRepository repo,AppProperties p){this.repo=repo;this.p=p;}
 public List<Instant> available(LocalDate date,ZoneId viewerZone){ ZoneId bz=p.businessZone(); Instant from=date.atStartOfDay(bz).toInstant(), to=date.plusDays(1).atStartOfDay(bz).toInstant(); Set<Instant> occupied=new HashSet<>(); repo.findByStatusAndStartsAtGreaterThanEqualAndStartsAtLessThan(BookingStatus.CONFIRMED,from,to).forEach(b->occupied.add(b.getStartsAt())); List<Instant> out=new ArrayList<>(); for(LocalTime t=p.workingHoursStart();!t.plusMinutes(30).isAfter(p.workingHoursEnd());t=t.plusMinutes(30)){Instant slot=ZonedDateTime.of(date,t,bz).toInstant();if(slot.isAfter(Instant.now())&&!occupied.contains(slot))out.add(slot);} return out; }
 public void assertBookable(Instant start){ if(start.getEpochSecond()%1800!=0) throw new IllegalArgumentException("A demo must start on a 30-minute boundary"); ZoneId z=p.businessZone(); LocalTime t=start.atZone(z).toLocalTime(); if(t.isBefore(p.workingHoursStart())||t.plusMinutes(30).isAfter(p.workingHoursEnd())||start.isBefore(Instant.now())) throw new IllegalArgumentException("The selected slot is outside available working hours"); if(repo.existsByStatusAndStartsAt(BookingStatus.CONFIRMED,start))throw new SlotTakenException(); }
 public static class SlotTakenException extends RuntimeException{} }
